import java.util.*;

public class Main {
    // ---------- repository 层：只做数据存取 ----------
    interface UserRepo {
        Map<String, Object> findById(long id);
        int callCount();
    }

    static class FakeDb implements UserRepo {
        private final Map<Long, Map<String, Object>> rows = new LinkedHashMap<>();
        private int calls = 0;

        FakeDb() {
            rows.put(1L, Map.of("id", 1L, "name", "alice", "role", "ADMIN"));
            rows.put(2L, Map.of("id", 2L, "name", "bob", "role", "USER"));
        }

        public Map<String, Object> findById(long id) {
            calls++;
            if (id == 98) throw new IllegalStateException("connection reset");
            return rows.get(id);   // id=99 不存在 -> 返回 null，交给上一层决定语义
        }

        public int callCount() { return calls; }

        List<String> columns() {
            List<String> ks = new ArrayList<>(rows.values().iterator().next().keySet());
            Collections.sort(ks);
            return ks;
        }
    }

    // ---------- DTO：不是 Entity，脱敏后才出接口 ----------
    record UserDto(long id, String name, boolean admin) {
        static UserDto of(Map<String, Object> row) {
            return new UserDto((Long) row.get("id"), (String) row.get("name"),
                    "ADMIN".equals(row.get("role")));
        }
    }

    // ---------- service 层：业务规则 + 缓存 ----------
    static class UserService {
        private final UserRepo repo;
        private final Map<Long, UserDto> cache = new LinkedHashMap<>();
        int cacheHits = 0;

        UserService(UserRepo repo) { this.repo = repo; }

        UserDto findById(long id) {
            UserDto hit = cache.get(id);
            if (hit != null) { cacheHits++; return hit; }
            Map<String, Object> row = repo.findById(id);
            if (row == null) throw new NoSuchElementException("user " + id + " not found");
            UserDto dto = UserDto.of(row);
            cache.put(id, dto);
            return dto;
        }
    }

    // ---------- controller 层：只做协议转换 ----------
    static class UserController {
        private final UserService service;
        UserController(UserService service) { this.service = service; }

        String get(long id) {
            try {
                UserDto d = service.findById(id);
                return "200 {\"id\":" + d.id() + ",\"name\":\"" + d.name() + "\",\"admin\":" + d.admin() + "}";
            } catch (NoSuchElementException e) {
                return "404 {\"error\":\"" + e.getMessage() + "\"}";
            } catch (RuntimeException e) {
                return "500 {\"error\":\"internal\"}";
            }
        }
    }

    public static void main(String[] args) {
        FakeDb db = new FakeDb();
        UserService svc = new UserService(db);
        UserController c = new UserController(svc);

        System.out.println("=== GET /api/users/{id} ===");
        System.out.println("  id=1   -> " + c.get(1));
        System.out.println("  id=1   -> " + c.get(1) + "   (2nd call served from cache)");
        System.out.println("  id=2   -> " + c.get(2));
        System.out.println("  id=99  -> " + c.get(99));
        System.out.println("  id=98  -> " + c.get(98));

        System.out.println();
        System.out.println("=== accounting (all numbers derived from the run) ===");
        System.out.println("  total requests     : 5");
        System.out.println("  repository calls   : " + db.callCount());
        System.out.println("  service cache hits : " + svc.cacheHits);
        System.out.println("  => the repeated id=1 never reached the repository again");

        System.out.println();
        System.out.println("=== DTO vs Entity: field sets read from the objects themselves ===");
        System.out.println("  entity columns (repo side) : " + db.columns());
        List<String> dto = new ArrayList<>();
        for (var rc : UserDto.class.getRecordComponents()) dto.add(rc.getName());
        System.out.println("  dto components (api side)  : " + dto);
        List<String> entityOnly = new ArrayList<>(db.columns());
        entityOnly.removeAll(dto);
        System.out.println("  entity-only, never serialized : " + entityOnly);

        System.out.println();
        System.out.println("=== error mapping belongs to the advice, not the controller body ===");
        System.out.println("  NoSuchElementException -> 404  (business: resource missing)");
        System.out.println("  other RuntimeException -> 500  (infrastructure: db unreachable)");
        System.out.println("  transaction boundary   -> service layer");
    }
}
